INSERT INTO hallazgo(hallazgo_id,caso_id,tipo,regla_analisis,version_regla,evidencia_a_json,evidencia_b_json,descripcion,estado,prioridad_revision) VALUES(1,309,'diferencia_fecha_cierre','comparacion_literal_fuentes','0.1','{"fuente":"Excel","pestana":"Convocatorias Abiertas","fila":2,"columna":"I","valor_literal":"18/11/2026 4:00:00 p. m."}','{"fuente":"PDF convocatoria","id":"2026-C2381","url":"https://drive.google.com/file/d/11e0uf_0IJ5dYra9RksPG1uIT9TkGXI9T/view?usp=drivesdk","valor_literal":"19/Nov/2026 04:00 p.m."}','Excel y PDF de convocatoria registran fechas de cierre diferentes. Requiere cotejo visual y examen de adendas; no constituye por sí solo irregularidad.','pendiente_cotejo_visual','normal');
INSERT INTO hallazgo(hallazgo_id,caso_id,tipo,regla_analisis,version_regla,evidencia_a_json,evidencia_b_json,descripcion,estado,prioridad_revision) VALUES(2,103,'codigo_interno_resultados_inconsistente','comparacion_literal_fuentes','0.1','{"fuente":"Excel","pestana":"Convocatorias Cerradas","fila":36,"codigo":"2026-C2312"}','{"fuente":"PDF resultados","titulo":"Resultados 2026-C2312","codigo_interno_literal":"2026-C2302","url":"https://drive.google.com/file/d/1BdKbtbIhlMQRwjKrWGJrYD3aGXhPuSB_/view?usp=drivesdk"}','El PDF vinculado como resultados de 2026-C2312 lleva ese código en el título, pero contiene 2026-C2302 como número de convocatoria. Verificar encabezado visual y correspondencia del enlace.','pendiente_cotejo_visual','normal');
INSERT INTO hallazgo(hallazgo_id,caso_id,tipo,regla_analisis,version_regla,evidencia_a_json,evidencia_b_json,descripcion,estado,prioridad_revision) VALUES(3,419,'codigo_repetido_en_hoja','comparacion_literal_fuentes','0.1','{"fuente":"Excel","pestana":"Convocatorias Cerradas","fila":25,"codigo":"2026-C2324"}','{"fuente":"Excel","pestana":"Convocatorias Cerradas","fila":26,"codigo":"2026-C2324"}','Existen dos filas de la hoja con código 2026-C2324. Se conservan como dos registros independientes hasta verificar si es duplicación legítima.','pendiente_cotejo_visual','normal');
INSERT INTO hallazgo(hallazgo_id,caso_id,tipo,regla_analisis,version_regla,evidencia_a_json,evidencia_b_json,descripcion,estado,prioridad_revision) VALUES(4,204,'revision_calidad_texto_resultados','comparacion_literal_fuentes','0.1','{"fuente":"PDF resultados","codigo":"2026-C2308","fragmentos_extraidos":"texto breve; ver documento enlazado"}',NULL,'El resultado vinculado a 2026-C2308 produjo una transcripción textual especialmente breve; no se infiere contenido ausente, pero se requiere comprobar el PDF original visualmente.','pendiente_cotejo_visual','normal');
